(7115705, 1085834, 30982, '<td valign="top">A nice start on shooting within a controlled environment.  Needs a bit more light, methinks, to keep it bright and clean.</td>', 'A nice start on shooting within a controlled environment.  Needs a bit more light, methinks, to keep it bright and clean.', '2013-10-14 21:17:27.000000', NULL, 1),
(7115706, 1085739, 30982, '<td valign="top">A lovely macro nature shot.</td>', 'A lovely macro nature shot.', '2013-10-14 21:18:02.000000', NULL, 1),
(7115707, 1085892, 30982, '<td valign="top">A good approach to a stock shot.  To really sell it, I think it needs to be a bit brighter overall, and the glass needs to be spotless.  Also, no bubbles in the wine.  Some of that can be done post processing.</td>', 'A good approach to a stock shot.  To really sell it, I think it needs to be a bit brighter overall, and the glass needs to be spotless.  Also, no bubbles in the wine.  Some of that can be done post processing.', '2013-10-14 21:20:34.000000', NULL, 1),
