(7115709, 1086017, 30982, '<td valign="top">Pink, and bubbles!  Kinda looks like a spaceship.</td>', 'Pink, and bubbles!  Kinda looks like a spaceship.', '2013-10-14 21:21:13.000000', NULL, 1),
(7115710, 1085257, 30982, '<td valign="top">I''m going to say this leans a bit more towards red than pink.  I''m not sold on the composition - I think maybe having more of the front of the flower than the back?</td>', 'I''m going to say this leans a bit more towards red than pink.  I''m not sold on the composition - I think maybe having more of the front of the flower than the back?', '2013-10-14 21:22:18.000000', NULL, 1),
