(7115715, 1085291, 30982, '<td valign="top">A very sweet environmental type portrait.  Works well for the challenge, too.</td>', 'A very sweet environmental type portrait.  Works well for the challenge, too.', '2013-10-14 21:24:11.000000', NULL, 1),
